/* ==========『作者：长夜何其多』日间全局桌面 ========== */

/* ⚠️ 重要提醒：
   1. 使用时请前往桌面 ➠ 壁纸 ➠ 透明遮罩滑杆 ➠ 将【壁纸遮罩】滑到 0% ❗❗❗
   2. 桌面 ➠ 底部导航 ➠ 浮标 ❗❗❗
*/

:root {
  --ico-r: 12px !important; 
  --dress-wg-radius: 12px !important; 
  --dress-app-ico-radius: var(--ico-r) !important;
  --desk-blur: 0px !important;
  --desk-mask: 0 !important;
  --wallpaper-blur: 0px !important;
  --desk-wallpaper-blur: 0px !important;
  --desk-glass-blur: 0px !important;
}

/* 1. 干掉原生遮罩 */
.desk-mask, [class*="wallpaper-mask"], [class*="desk-mask"] {
  display: none !important;
}

/* 2. 把图源死死钉在全屏最底层 */
html, body, #app, .device, .page-container, .desk {
  background-color: transparent !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important; 
  opacity: 1 !important; 
}

/* ==========================================
   3. 核心外壳：单层玻璃 + 图源底色
   ========================================== */
.wg-profile, .wg-note, .wg-cd, .wg-hero, .wg-quote, .tile.wg, [class*="wg-"] {
  background-image: linear-gradient(rgba(255, 255, 255, 0.15), rgba(255, 255, 255, 0.15)), url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important; 

  border: 1px solid rgba(255, 255, 255, 0.6) !important;
  border-radius: 12px !important; 

  width: calc(100% - 16px) !important; 
  margin: 8px auto !important; 
  box-sizing: border-box !important;
  box-shadow: none !important; 
}

/* ==========================================
   4. 核心操作：掏空内脏，但【绝对放行图片】！
   ========================================== */
.wg-profile *, .wg-note *, .wg-cd *, .wg-hero *, .wg-quote *, [class*="wg-"] * {
  /* 取消内部纯色块和边框，变成单层 */
  background-color: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}

/* 👇 音乐播放器封面复活术：精准定位，绝不误伤！ */
[class*="music"] img, 
[class*="player"] img, 
[class*="cover"], 
[class*="album"], 
[class*="art"] {
  opacity: 1 !important;
  display: block !important;
  border-radius: 8px !important; /* 封面图小圆角 */
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.15) !important; 
}

/* 如果封面是用背景图写的，强制恢复它的显示属性（不再用 initial 抹除） */
[class*="music"] [class*="cover"], 
[class*="player"] [class*="cover"],
[class*="wg-"][class*="cover"], 
[class*="wg-"][class*="album"] {
  background-color: rgba(255, 255, 255, 0.2) !important; 
  background-size: cover !important;
  background-position: center !important;
}

/* 保留一点内部的分割线 */
.wg-profile [class*="divider"], 
.wg-note [class*="divider"], 
[class*="wg-"] hr {
  background-color: rgba(255, 255, 255, 0.5) !important;
  height: 1px !important;
}

/* ==========================================
   5. 图标网格（保持原样，只切圆角）
   ========================================== */
.app-box .ico img, .tile.app .ico img { border-radius: 12px !important; }
.desk[data-p] .app-box .ico, .tile.app .ico {
  border: 1px solid rgba(255, 255, 255, 0.95) !important;
  box-shadow: 0 4px 12px rgba(220, 150, 185, 0.2) !important;
  border-radius: 12px !important;
}
.app-box .ico img, .tile.app .ico img, .dock-app-ico {
  filter: sepia(0.2) hue-rotate(310deg) saturate(1.1) brightness(1.05) contrast(0.95) !important;
}

/* ==========================================
   6. 底部栏：图源 + 圆角同步
   ========================================== */
.dock, .dock-bar, .dock-wrap, .foot {
  background-image: linear-gradient(rgba(255, 255, 255, 0.35), rgba(255, 255, 255, 0.35)), url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
  border-top: 1px solid rgba(255, 255, 255, 0.4) !important;
  border-radius: 0 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
.dock-app-ico, .dock-app-empty { 
  border-radius: 12px !important; 
  border: 1px solid rgba(255, 255, 255, 0.8) !important; 
}

/* ==========================================
   7. 文字强保护（字黑+发光）
   ========================================== */
.wg-profile *, .wg-note *, .wg-cd *, [class*="wg-"] *, .app-box span {
  color: #4a3340 !important;
  text-shadow: 0 1px 3px rgba(255, 255, 255, 0.95), 0 0 2px rgba(255, 255, 255, 0.9) !important;
  font-weight: 600 !important;
}
.status-bar, .top-bar, .header, .nav-bar, .title-bar, .status, .status-bar *, .top-bar * {
  color: #4a3340 !important; 
  background: transparent !important;
  text-shadow: 0 1px 3px rgba(255, 255, 255, 0.9) !important;
}
